-- Append-only expansion: 60 recipes, 360 task briefs, 1080 intensity variants.
-- Historical template IDs/content and accepted snapshots remain unchanged.
-- Task briefs are separate variant keys, not fake revision/version numbers.
-- All briefs still share the recipe family for reward cooldown enforcement.
alter table public.quest_templates add column if not exists variant_key text not null default 'default';
alter table public.quest_templates drop constraint if exists quest_templates_family_id_intensity_version_key;
do $$
begin
  if not exists (select 1 from pg_constraint where conrelid = 'public.quest_templates'::regclass and conname = 'quest_templates_family_intensity_variant_version_key') then
    alter table public.quest_templates add constraint quest_templates_family_intensity_variant_version_key unique(family_id,intensity,variant_key,version);
  end if;
  if not exists (select 1 from pg_constraint where conrelid = 'public.quest_templates'::regclass and conname = 'quest_templates_variant_key_matches_content') then
    alter table public.quest_templates add constraint quest_templates_variant_key_matches_content check (
      variant_key ~ '^[a-z_]+$' and length(variant_key) <= 40
      and variant_key = coalesce(content->>'variantKey','default')
    );
  end if;
end $$;

-- Generated from shared/catalog.ts by node scripts/seed-catalog.mjs.
-- Authored activity variations, not live events or sourced venue inventory.
-- No sponsors, merchant inventory, wallets, or redeemable offers.
-- Published versions are immutable; new editorial content needs a new version and ID.
on conflict (id) do nothing;
